type agreementNeutralPunctuationHeadingSource struct {
	Original, PrivateReading    agreementNeutralHeadingSource
	Native, PrivateNative       agreementNativeHeadingSource
	IDs, PrivateIDs             []string
	Private                     string
	OriginalSpan, ProjectedSpan graph.Span
	Ordinal                     int
	Valid                       bool
}

// A punctuation-only heading receives a fallback name on the page. Both
// grammars must bind its original punctuation byte and the whole name allocation
// before that fallback can own a missing check name.
func agreementNeutralPunctuationHeadingReading(body string, f *agreementFailure, page *agreementHTML) agreementNeutralPunctuationHeadingSource {
	r := agreementNeutralPunctuationHeadingSource{Ordinal: -1}
	if f == nil || page == nil || f.Property != "P4" || f.Identity != "literal-heading-id" || f.Direction != "page-only" || f.Multiplicity != 1 || f.Tuple != (agreementCitation{}) || !f.PagePresent || f.JudgeAccepted || f.ExcerptFound || f.Cut != "" || strings.Contains(body, "q") {
		return r
	}
	r.Original = agreementNeutralHeadingRead(body)
	a := &r.Original
	if !a.Valid || !slices.Equal(a.IDs, page.Headings) || a.Native.Names[f.Fragment] {
		return r
	}
	r.IDs, r.Native = a.IDs, a.Native
	for i, id := range r.IDs {
		if id == f.Fragment {
			if r.Ordinal >= 0 {
				return r
			}
			r.Ordinal = i
		}
	}
	if r.Ordinal < 0 || r.Ordinal >= len(a.Page.Headings) {
		return r
	}
	span := a.Page.Headings[r.Ordinal]
	if span.Start < 0 || span.Stop <= span.Start || span.Stop > len(a.Positions) {
		return r
	}
	found := -1
	if span.Stop-span.Start == 1 && a.Projected[span.Start:span.Stop] == "!" && a.Page.Bases[r.Ordinal] == "section" && a.Page.Checks[r.Ordinal] == "section" {
		at := span.Start
		protected := false
		for _, code := range a.Page.Code {
			if code.Start <= at && at < code.Stop {
				protected = true
			}
		}
		for _, field := range a.Page.Fields {
			if field.Span.Start <= at && at < field.Span.Stop {
				protected = true
			}
		}
		if !protected {
			found = at
		}
	}
	if found < 0 {
		return r
	}
	r.ProjectedSpan = graph.Span{Start: found, Stop: found + 1}
	start := a.Positions[found]
	if start < 0 || start >= len(body) || body[start] != a.Projected[found] {
		return r
	}
	r.OriginalSpan = graph.Span{Start: start, Stop: start + 1}
	private := []byte(body)
	private[start] = 'q'
	r.Private = string(private)
	r.PrivateReading = agreementNeutralHeadingRead(r.Private)
	b := &r.PrivateReading
	if !b.Valid || !slices.Equal(a.Positions, b.Positions) || !slices.Equal(a.Native.Check.Targets, b.Native.Check.Targets) {
		return r
	}
	expected := []byte(a.Projected)
	expected[found] = 'q'
	if string(expected) != b.Projected || !cmp.Equal(a.Page.Headings, b.Page.Headings) || !cmp.Equal(a.Page.Code, b.Page.Code) || !cmp.Equal(a.Page.Fields, b.Page.Fields) || len(a.Page.Bases) != len(b.Page.Bases) || len(a.Page.Checks) != len(b.Page.Checks) {
		return r
	}
	for i := range a.Page.Bases {
		if i == r.Ordinal {
			if a.Page.Bases[i] == b.Page.Bases[i] || a.Page.Checks[i] == b.Page.Checks[i] {
				return r
			}
		} else if a.Page.Bases[i] != b.Page.Bases[i] || a.Page.Checks[i] != b.Page.Checks[i] {
			return r
		}
	}
	r.PrivateIDs, r.PrivateNative = b.IDs, b.Native
	r.Valid = true
	return r
}
func agreementNeutralPunctuationHeadingEquation(ids []string, names map[string]bool, failures []agreementFailure) bool {
	expected := map[string]int{}
	for _, id := range ids {
		if !names[id] {
			f := agreementFailure{Property: "P4", Identity: "literal-heading-id", Fragment: id, Direction: "page-only", Multiplicity: 1, PagePresent: true}
			expected[agreementSignature(&f)]++
		}
	}
	actual := map[string]int{}
	for i := range failures {
		f := &failures[i]
		if f.Property == "P4" {
			actual[agreementSignature(f)]++
		}
	}
	return maps.Equal(expected, actual)
}
func agreementNeutralPunctuationHeadingProjection(source *agreementNeutralPunctuationHeadingSource, before, after []agreementFailure, page, privatePage *agreementHTML, diagnostics, privateDiagnostics []render.Diagnostic) bool {
	if source == nil || page == nil || privatePage == nil || !source.Valid || !slices.Equal(source.IDs, page.Headings) || !slices.Equal(source.PrivateIDs, privatePage.Headings) || !cmp.Equal(diagnostics, privateDiagnostics) || !agreementNeutralPunctuationHeadingEquation(source.IDs, source.Native.Names, before) || !agreementNeutralPunctuationHeadingEquation(source.PrivateIDs, source.PrivateNative.Names, after) {
		return false
	}
	a, b := *page, *privatePage
	a.Headings = nil
	b.Headings = nil
	if !cmp.Equal(a, b) {
		return false
	}
	original, private := map[string]int{}, map[string]int{}
	for i := range before {
		f := &before[i]
		if f.Property != "P4" {
			original[agreementSignature(f)]++
		}
	}
	for i := range after {
		f := &after[i]
		if f.Property != "P4" {
			private[agreementSignature(f)]++
		}
	}
	return maps.Equal(original, private)
}
func agreementNeutralPunctuationHeadingDifference(c agreementCase, f *agreementFailure, html string, page *agreementHTML, diagnostics []render.Diagnostic, failures []agreementFailure) (kind, authority, wrong string) {
	if f == nil || page == nil || c.Title != "" || len(c.Companions) != 0 {
		return "", "", ""
	}
	for i := range agreementNeutralPunctuationHeadingDeclarations() {
		r := &agreementNeutralPunctuationHeadingDeclarations()[i]
		if c.Body != r.Body || agreementSignature(f) != r.Selected {
			continue
		}
		if html != r.HTML || !cmp.Equal(*page, r.Page) || !cmp.Equal(diagnostics, r.Diagnostics) || !maps.Equal(agreementMixedCurrent(failures), agreementMixedCurrent(r.Before)) {
			return "", "", ""
		}
		source := agreementNeutralPunctuationHeadingReading(c.Body, f, page)
		if !cmp.Equal(source, r.Source) || !agreementNeutralPunctuationHeadingProjection(&source, r.Before, r.After, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics) {
			return "", "", ""
		}
		return "debt", "#1011 stage 8", "judge"
	}
	return "", "", ""
}
func agreementNeutralPunctuationHeadingSelected(t *testing.T, r *agreementNeutralPunctuationHeadingDeclaration) agreementFailure {
	t.Helper()
	var selected agreementFailure
	seen := 0
	for i := range r.Before {
		f := &r.Before[i]
		if agreementSignature(f) == r.Selected {
			selected = *f
			seen++
		}
	}
	if seen != 1 {
		t.Fatal("caught: unique neutral punctuation heading declaration")
	}
	return selected
}
